        for c in range(w - 1):
            block = {(r, c), (r, c + 1), (r + 1, c), (r + 1, c + 1)}
            if block <= occupied:
                tiles.append((block, 1))
            for mr, mc in ((0, 0), (0, 1), (1, 0), (1, 1)):
                cells = block - {(r + mr, c + mc)}
                if cells <= occupied:
